    }

    if (toolUseId != null) {
      json['toolUseId'] = toolUseId;
    }

    if (blockId != null) {
      json['blockId'] = blockId;
    }

    if (mediaType != null) {
      json['mediaType'] = mediaType;
    }

    if (size != null) {
      json['size'] = size;
    }

    return json;
  }
}

