  /// Yes or no. There is no third value: silence is handled by the deadline, and it denies.
  final String decision;

  /// How far the decision reaches. Absent means `once`. `session` leaves rules that die with the session; `project` and `always` persist rules — the patterns of the chosen `reach`, with the configured default lifetime — that answer future requests without asking and are revoked through `DELETE /permission-rules/:ruleId`. A scope with no pattern for the chosen reach is `INVALID_INPUT`.
  final String? scope;

  /// Which of the request's `reaches` the rules left by `session`, `project` or `always` take. Absent means `exact`. A reach the request did not offer is `INVALID_INPUT`, and the request stays open. Ignored for `once`.
  final String? reach;

  /// Why it was refused. Required whenever `decision` is `deny` — the schema carries the condition, so no end has to remember it.
  final String? reason;

  /// The answers to a question (`interaction` on the request), one per question, and required for an `allow` of one — a rule the schema cannot carry, because this payload does not say what was asked: the backend checks it against the questions it published, and refuses with `PERMISSION_ANSWERS_INVALID` (the request stays open). Never on a `deny`, and never on a request that is not a question. `scope` and `reach` are ignored on a question: it is `once`.
  final List<QuestionAnswer>? answers;

  /// A JSON map with the absent optional fields left out.
  Map<String, Object?> toJson() {
    final Map<String, Object?> json = <String, Object?>{
      'requestId': requestId,
      'decision': decision,
    };

    if (scope != null) {
      json['scope'] = scope;
    }

    if (reach != null) {
      json['reach'] = reach;
    }

    if (reason != null) {
      json['reason'] = reason;
    }

    if (answers != null) {
      json['answers'] = answers?.map((item) => item.toJson()).toList(growable: false);
    }

    return json;
  }
}

/// Whether [json] satisfies the conditional requirements of [PermissionResolvePayload].
///
/// `reason` is also required when `decision`
/// is `deny` — the reason goes into the audit trail and back to the agent as a message; a refusal nobody can account for is a refusal nobody can learn from.
bool permissionResolvePayloadConditionalsHold(Map<String, Object?> json) {
  if (json['decision'] == 'deny' && json['reason'] is! String) {
    return false;
  }

  return true;
}

/// Whether [json] keeps within the bounds the schema gives [PermissionResolvePayload].
bool permissionResolvePayloadLimitsHold(Map<String, Object?> json) {
  if (json['answers'] is List<Object?> && (json['answers']! as List<Object?>).length > 4) {
    return false;
  }

  return true;
}

/// `POST /devices`, `POST /devices/:deviceId/approval` and `DELETE /devices/:deviceId/approval`: one device, as the client sees it — the same shape as one entry of `DeviceList.devices`, named again rather than declared twice (plan 28, B-48).
typedef DevicePayload = Device;

/// `POST /engines/claude/diagnostics/model-check`: one turn with a fixed minimal prompt, no tools, one turn, a spending ceiling — the only thing this plan does that spends quota, and only on a click (plan 13, B-12, D-08). The same shape `GET /engines/claude/installation`'s `lastModelCheck` carries, named again rather than declared twice (plan 28, B-48).
typedef ModelCheckOutcomePayload = ModelCheckOutcome;

/// `POST /engines/:engine/mcp-servers`, `PUT`/`PATCH /engines/:engine/mcp-servers/:id`: one server, after the write (plan 13, B-19). `DELETE` of the same resource answers `204` with no body — see `scripts/contracts-route-exceptions.json`.
typedef McpServerDetailPayload = McpServer;

/// `POST /notifications`: keeps a notification — `201` when new, `200` with the one already kept under the same client id. The same shape as one entry of `NotificationPage.items`, named again rather than declared twice (plan 28, B-48).
typedef NotificationPayload = Notification;

/// `POST /workspaces/open-folders`: `201` with the new tab, `200` with the one already open — the same shape as one entry of `OpenFolders.folders`, named again rather than declared twice (plan 28, B-48).
typedef OpenFolderEntryPayload = OpenFolderEntry;

/// `GET /permission-rules/:ruleId`, `POST /permission-rules` and `DELETE /permission-rules/:ruleId`: one rule, whatever its state — the same shape as one entry of `PermissionRuleList.rules`, named again rather than declared twice (plan 28, B-48).
typedef PermissionRulePayload = PermissionRule;

/// `PUT /engines/:engine/project-mcp-approvals`: the entry just approved, at the digest the body carried (plan 13, B-24; D-11). `DELETE` of the same resource rejects an entry and answers `204` with no body — see `scripts/contracts-route-exceptions.json`.
typedef ProjectMcpServerApprovalPayload = ProjectMcpServer;
